"""AQS-BLD-018 enclosure, floor plates, stairs and egress (X-BLD-05, A-M-213). Occupant load per level by IBC 1004.5 function factors;
two exits per level (IBC 1006.3.3); stair width = max(1,118 mm, 7.6 mm per occupant) (IBC 1005.3.1, 1011.2); travel distance to an exit
stair from the farthest plate corner against 76 m (F-1, sprinklered, IBC 1017.2). Stairs and the levels they serve come from
models/freecad/building_stack.py geometry (params.py datums). Enclosure UA from IECC 2021 C402 opaque U-factors; design heat loss at the
AQS-SITE-002 99.6 % heating dry bulb. Floor plates from AQS-BLD-016. Run after _frame_check.py."""
import json, math, os, sys
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); os.chdir(R); sys.path.insert(0, R); sys.path.insert(0, os.path.join(R, 'models/freecad'))
from flow_graph.param.refs import cite
for k in ('IBC2021_CH10', 'IECC2021_C402', 'NFPA101_2024'): cite(k)
import params as P
Lp, Wp = P.PLATE_L, P.PLATE_W; A = Lp*Wp/1e6; z0r = P.HYDRO_RES_Z0; clr = P.HYDRO_RES_CLEAR
LV = [('L-2', P.Z_Lm2, 'lower reservoir and catch (maintenance only)', 27.9, 0.15), ('L-1', P.Z_Lm1, 'process (industrial)', 9.3, 1.0),
      ('L0', P.Z_L0, 'process and shop (industrial)', 9.3, 1.0), ('L1', P.Z_L1, 'habitation (residential) + farm (agricultural storage)', (18.6 + 27.9)/2, 1.0),
      ('L2', P.Z_L2, 'farm and roof tank (storage)', 27.9, 1.0)] + [(f'R{i+1}', z0r + i*clr, 'upper reservoir (maintenance walkway only)', 27.9, 0.15) for i in range(P.HYDRO_RES_LEVELS)] + [('ROOF', P.Z_ROOF, 'roof PV (maintenance)', 27.9, 1.0)]
z_top = max(P.Z_L2 + 2000, P.Z_ROOF + 2000)
ST = [('STAIR_P', P.Z_L0, z_top, P.STAIR_BOX), ('STAIR_S1', P.Z_L0, max(P.Z_L2, P.Z_ROOF), P.STAIR_BOX), ('STAIR_S2', P.Z_L0, P.Z_L2, P.STAIR_BOX),
      ('STAIR_MAINT', P.Z_Lm2, P.Z_L0 + 500, P.STAIR_MAINT_W), ('STAIR_SERVICE', P.Z_Lm2, P.Z_L0, min(P.STAIR_SERVICE_L, P.STAIR_SERVICE_W))]
POS = {'STAIR_P': (P.CORE_X + 1300, P.CORE_Y + 2500), 'STAIR_S1': (1400, Wp - 1400), 'STAIR_S2': (Lp - 1400, 1400), 'STAIR_MAINT': (P.CORE_X + 700, P.CORE_Y + 6200), 'STAIR_SERVICE': (P.STAIR_SERVICE_X + 1200, P.STAIR_SERVICE_Y + 1800)}
rows = []; bad = 0
for lv, z, use, f, frac in LV:
    occ = math.ceil(A*frac/f); s = [n for n, a, b, w in ST if a <= z <= b]; need_w = max(1118, 7.6*occ)
    cl = min(((w - 300)/2 if w >= 2400 else w - 150) for n, a, b, w in ST if n in s) if s else 0      # clear width per flight
    corners = [(0, 0), (Lp, 0), (0, Wp), (Lp, Wp)]
    td = max(min(abs(cx - POS[n][0]) + abs(cy - POS[n][1]) for n in s) for cx, cy in corners)/1000 if s else float('inf')
    ok = len(s) >= 2 and cl >= need_w and td <= 76; bad += not ok
    rows.append((lv, z/1000, use, occ, ', '.join(s) or '-', len(s), need_w, cl, td, 'pass' if ok else 'FAIL'))
H_above = P.Z_ROOF/1000; per = 2*(Lp + Wp)/1000; Uw, Ur = 0.534, 0.199; dT = 21 - (-7.2)
UA = Uw*per*H_above + Ur*A; Q = UA*dT/1000
md = ['# Enclosure, floor plates, stairs and egress', '', 'Document number: AQS-BLD-018', 'Revision: A', 'Date: 2026-10-16', 'Authority: AQS-PLAN-007 X-BLD-05; AQS-EGR-001 method. Generated by `docs-authority/_egress_env.py`. Study; not a PE stamp. A-M-213.', '',
 '## Egress per level', '', '| Level | z m | Use | Occupants | Stairs serving | Exits | Stair width needed mm | Clear provided mm | Travel to stair m (limit 76) | Result |', '|---|---|---|---|---|---|---|---|---|---|']
md += [f'| {a} | {b:.1f} | {c} | {d} | {e} | {f} | {g:.0f} | {h:.0f} | {i:.1f} | {j} |' for a, b, c, d, e, f, g, h, i, j in rows]
md += ['', f'Failing levels: {bad}. Changes made: stair boxes 2,400 -> 2,600 mm (STAIR_BOX) and STAIR_MAINT 1,200 -> 1,300 mm so each flight has 1,150 mm clear (IBC 1011.2 needs 1,118; the old 2,400 box gave 1,100); STAIR_P and STAIR_S1 now run to the roof (models/freecad/building_stack.py); before this the reservoir levels R1-R3 and the roof had no stair (the stairs stopped at L2 + 2 m).',
 '', '## Floor plates', '', f'Every suspended level is a {P.SLAB_THK} mm concrete slab on the AQS-BLD-016 steel beams over the {Lp/1000:.0f} x {Wp/1000:.0f} m plate ({A:.0f} m2); reservoir floors and walls are ACI 350 water-retaining; L-2 bears on the AQS-BLD-017 mat. Horizontal assemblies: 2 h between levels (AQS-HSE-001), 3 h between life and process levels.',
 '', '## Enclosure', '', f'Above grade: {per:.0f} m perimeter x {H_above:.1f} m, insulated metal wall U {Uw} W/m2K; roof {A:.0f} m2 U {Ur} W/m2K (IECC 2021 C402, zone 3). UA {UA:,.0f} W/K; design heat loss {Q:.1f} kW at {dT:.1f} K (AQS-SITE-002 99.6 %). Below grade: cast basement walls, waterproofed, drained to the CATCH_TANK sump (AQS-BLD-017).']
open('docs-authority/ENCLOSURE_EGRESS.md', 'w').write('\n'.join(md) + '\n'); print(bad, [r for r in rows if r[-1] == 'FAIL'])
